def transform(grid):
    out = [row[:] for row in grid[:3]]
    # At empty cells, overlay the lower layers with priority 4, then 8, then 2.
    for r in range(3):
        for c in range(6):
            if out[r][c] == 0:
                for color, layer in ((4, grid[3:6]), (8, grid[9:12]), (2, grid[6:9])):
